"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Step 0 check (plan section 10 risks, with item 3): the speaker-ID model's training data must not overlap our voices.

The model (speechbrain/spkrec-ecapa-voxceleb) is trained on VoxCeleb1 and VoxCeleb2 (celebrities from interview
videos). The user and assistant voices are Kokoro voices (synthetic, no real person) and, in the unseen Piper subset,
Piper en_US-libritts-high (LibriTTS: volunteer audiobook readers). The TV voices are VoxPopuli (European Parliament
speeches); VoxPopuli speaker IDs are the Parliament's member IDs, so names come from the Parliament's open data
(terms 7-9 lists plus single lookups). Names are compared with the VoxCeleb1 and VoxCeleb2 names (the model's
training data; VoxCeleb2 names from the VoxCeleb enrichment release, hechmik/voxceleb_enrichment_age_gender) and,
as a broader reference, with the VGGFace2 training names (VoxCeleb2 identities are a subset of VGGFace2).
Exact match: normalized "given family" equals a name. Loose match: same first given token and same last family token.
For test and replication only counts are printed; names only for train and dev. Writes the exclusion list
results/step0_v04/tv_speaker_exclude.json (in VoxCeleb, or no name), read by p1v4_units.Assets for new units.
usage: python -I scripts/step0v4_speaker_overlap.py <vox1_meta.csv> <vox2 meta with names> <VGGFace2 train labels .npy>
       <EP data dir>
  (the copies used on 2026-11-15 are in data/external/speaker_overlap/: vox1_meta.csv, vox2_meta_with_names.csv,
   vggface2_train_labels.npy, ep_meps/)
"""
import csv
import glob
import json
import os
import re
import sys
import unicodedata
from collections import defaultdict

import numpy as np


def norm(s):
    s = unicodedata.normalize("NFKD", str(s))
    s = "".join(c for c in s if not unicodedata.combining(c))
    s = re.sub(r"[_.\-'’]", " ", s.lower())
    return " ".join(s.split())


def main(vox1, vox2, vgg2, ep_dir):
    celeb = defaultdict(set)
    with open(vox1, encoding="utf-8") as f:
        for row in csv.reader(f, delimiter="\t"):
            if len(row) > 1 and row[0].startswith("id1"):
                celeb[norm(row[1])].add("VoxCeleb1")
    with open(vox2, encoding="utf-8") as f:
        for row in csv.reader(f, delimiter="	"):
            if len(row) > 1 and row[1].strip().startswith("id0"):
                celeb[norm(row[0])].add("VoxCeleb2")
    for n in np.load(vgg2, allow_pickle=False):
        celeb[norm(n)].add("VGGFace2-train")
    celeb.pop("", None)
    by_ends = defaultdict(set)
    for c in celeb:
        t = c.split()
        if len(t) >= 2:
            by_ends[(t[0], t[-1])].add(c)
    mep = {}
    for f in sorted(glob.glob(os.path.join(ep_dir, "meps_term*.json"))):
        for m in json.load(open(f, encoding="utf-8"))["data"]:
            mep[m["identifier"]] = m
    for f in sorted(glob.glob(os.path.join(ep_dir, "single", "*.json"))):
        d = json.load(open(f, encoding="utf-8"))
        for m in (d["data"] if isinstance(d.get("data"), list) else [d]):
            mep[m["identifier"]] = m
    tv = json.load(open("results/step0_v04/tv_speech.json", encoding="utf-8"))["manifest"]
    spk = defaultdict(set)
    for m in tv.values():
        spk[m["split"]].add(str(m["speaker"]))
    res = {"names": {k: sum(k in v for v in celeb.values()) for k in ("VoxCeleb1", "VoxCeleb2", "VGGFace2-train")},
           "ep_members_known": len(mep), "per_split": {}}
    exclude = set()
    for split in ("train", "dev", "test", "replication"):
        exact, loose, unnamed = [], [], 0
        for sid in sorted(spk[split]):
            m = mep.get(sid)
            if m is None:
                unnamed += 1
                continue
            full = norm(f"{m.get('givenName', '')} {m.get('familyName', '')}")
            cands = {full, norm(m.get("label", ""))}
            hit = sorted(c for c in cands if c in celeb)
            g, fam = norm(m.get("givenName", "")).split(), norm(m.get("familyName", "")).split()
            near = sorted(by_ends.get((g[0], fam[-1]), set())) if g and fam else []
            if hit:
                exact.append((sid, m.get("label"), hit, sorted(celeb[hit[0]])))
            elif near:
                loose.append((sid, m.get("label"), near, sorted(set().union(*(celeb[c] for c in near)))))
        vox = lambda L: [x for x in L if {"VoxCeleb1", "VoxCeleb2"} & set(x[3])]
        exclude |= {x[0] for x in vox(exact) + vox(loose)} | {sid for sid in spk[split] if sid not in mep}
        row = {"tv_speakers": len(spk[split]), "named": len(spk[split]) - unnamed, "unnamed": unnamed,
               "in_voxceleb_exact": len(vox(exact)), "in_voxceleb_loose_only": len(vox(loose)),
               "any_list_exact": len(exact), "any_list_loose_only": len(loose)}
        if split in ("train", "dev"):
            row["exact"] = exact
            row["loose_only"] = loose
        else:
            row["matched_speaker_ids"] = {"in_voxceleb": [x[0] for x in vox(exact) + vox(loose)],
                                          "any_list": [x[0] for x in exact + loose]}
        res["per_split"][split] = row
    json.dump(res, open("results/step0_v04/speaker_model_overlap.json", "w", encoding="utf-8"), indent=1,
              ensure_ascii=False)
    json.dump({"rule": "TV speakers in VoxCeleb1/2 (the speaker-ID model's training data) or without a name (cannot be "
                       "checked); plan 8.4", "exclude": sorted(exclude)},
              open("results/step0_v04/tv_speaker_exclude.json", "w", encoding="utf-8"), indent=1)
    print("excluded TV speakers:", len(exclude))
    print("names", res["names"], "| EP members known", len(mep))
    for split, row in res["per_split"].items():
        print(split, {k: v for k, v in row.items() if not isinstance(v, (list, dict))})
        for k in ("exact", "loose_only"):
            for x in row.get(k, []):
                print("   ", k, x)


if __name__ == "__main__":
    main(*sys.argv[1:5])
